import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long k = nextLong();
        long[] score = new long[n], distance = new long[n];
        List<Integer> order = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            score[i] = nextLong();
            distance[i] = nextLong();
            if (nextInt() == 1) order.add(i);
        }
        // rating desc, distance asc, index asc
        order.sort((x, y) -> {
            if (score[x] != score[y]) return Long.compare(score[y], score[x]);
            if (distance[x] != distance[y]) return Long.compare(distance[x], distance[y]);
            return Integer.compare(x, y);
        });
        int take = (int) Math.min(k, order.size());
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < take; i++) {
            if (i > 0) out.append(' ');
            out.append(order.get(i));
        }
        System.out.println(out);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"sort"
	"strconv"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	k := nextInt()
	score := make([]int64, n)
	distance := make([]int64, n)
	order := []int{}
	for i := 0; i < n; i++ {
		score[i], distance[i] = nextInt(), nextInt()
		if nextInt() == 1 {
			order = append(order, i)
		}
	}
	// rating desc, distance asc, index asc
	sort.Slice(order, func(a, b int) bool {
		x, y := order[a], order[b]
		if score[x] != score[y] {
			return score[x] > score[y]
		}
		if distance[x] != distance[y] {
			return distance[x] < distance[y]
		}
		return x < y
	})
	take := min(int(k), len(order))
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for i := 0; i < take; i++ {
		if i > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.Itoa(order[i]))
	}
	w.WriteByte('\n')
}
